using System.Collections;
using UnityEngine;
using UnityEngine.UI;

namespace Astrea;

public class RuneInstanceOutlineHandler : ActionInstanceOutlineHandler
{
	[Header("Texture Outline")]
	[SerializeField]
	protected float defaultOutlineBrightness;

	[SerializeField]
	private float mustUseDefaultBrightness;

	[SerializeField]
	protected float shinyOutlineBrightness;

	[Header("Components")]
	[SerializeField]
	protected Image outlineImage;

	protected Coroutine shineCoroutine;

	private void Awake()
	{
		playerDiceOutlineRuntime = Object.Instantiate(playerDiceOutline);
		mustUseOutlineRuntime = Object.Instantiate(mustUseOutline);
		highlightOutlineRuntime = Object.Instantiate(highlightOutline);
		outlineImage.material.SetFloat("_Brightness", 0f);
	}

	public void HighlightRuneInstance()
	{
		outlineImage.material = highlightOutlineRuntime;
	}

	public void RemoveHighlightRuneInstance()
	{
		UpdateOutlineAndMustUse();
		outlineImage.material.SetFloat("_Brightness", mustUse ? mustUseDefaultBrightness : defaultOutlineBrightness);
	}

	public override void UpdateOutlineAndMustUse()
	{
		base.UpdateOutlineAndMustUse();
		if (mustUse)
		{
			outlineImage.material = mustUseOutlineRuntime;
			outlineImage.material.SetFloat("_Brightness", 0f);
		}
		else
		{
			outlineImage.material = playerDiceOutlineRuntime;
			outlineImage.material.SetFloat("_Brightness", 0f);
		}
	}

	public override void ToggleOutline(bool toggle, bool animation = true)
	{
		if (!base.gameObject.activeInHierarchy)
		{
			return;
		}
		if (!animation)
		{
			outlineImage.materialForRendering.SetFloat("_Brightness", (!toggle) ? 0f : (mustUse ? mustUseDefaultBrightness : defaultOutlineBrightness));
			return;
		}
		if (shineCoroutine != null)
		{
			StopAllCoroutines();
			shineCoroutine = null;
		}
		_ = outlineImage.material;
		float startValue = outlineImage.materialForRendering.GetFloat("_Brightness");
		float targetValue = ((!toggle) ? 0f : (mustUse ? mustUseDefaultBrightness : defaultOutlineBrightness));
		shineCoroutine = StartCoroutine(CoroutineUtility.CurveRoutine(0.2f, delegate(float t, float v)
		{
			float value = Mathf.Lerp(startValue, targetValue, v);
			outlineImage.materialForRendering.SetFloat("_Brightness", value);
		}, delegate
		{
			shineCoroutine = null;
		}));
	}

	protected override void PlayActionBrightnessAnimation()
	{
		if (shineCoroutine != null)
		{
			StopCoroutine(shineCoroutine);
		}
		shineCoroutine = StartCoroutine(ActionBrightnessAnimation());
	}

	private IEnumerator ActionBrightnessAnimation()
	{
		if (!actionInstance.Discarding)
		{
			Shake();
			_ = outlineImage.material;
			float startValue = outlineImage.material.GetFloat("_Brightness");
			float targetValue = shinyOutlineBrightness;
			yield return StartCoroutine(CoroutineUtility.CurveRoutine(brightnessOnDurationReference.Value, brightnessOnCurveReference.Value, delegate(float t, float v)
			{
				float value2 = Mathf.Lerp(startValue, targetValue, v);
				outlineImage.material.SetFloat("_Brightness", value2);
			}));
			yield return new WaitForSeconds(brightnessStayBrightDurationReference.Value);
			float brightnessValue = defaultOutlineBrightness;
			if (mustUse)
			{
				brightnessValue = mustUseDefaultBrightness;
			}
			startValue = shinyOutlineBrightness;
			targetValue = brightnessValue;
			yield return StartCoroutine(CoroutineUtility.CurveRoutine(brightnessOffDurationReference.Value, brightnessOffCurveReference.Value, delegate(float t, float v)
			{
				float value = Mathf.Lerp(startValue, targetValue, v);
				outlineImage.material.SetFloat("_Brightness", value);
			}));
			yield return InvokeAlternatives.WaitForFrames(3);
			outlineImage.material.SetFloat("_Brightness", brightnessValue);
			shineCoroutine = null;
		}
	}
}
